function serveIfInitMsg(msg) {
    const req_ = msg.data;
    if (typeof req_ == "object"){
        if (req_.type == "init") {
            if (req_.buf) {
                var shared = req_.buf;
                registerSocketBuffer(shared);
                registerConnBuffer(req_.toBuf, req_.fromBuf);
                registerMetaBuffer(req_.metaFromBuf);
            }
            return {
                stackWasmURL: req_.stackWasmURL
            };
        }
    }

    return null;
}

